<script setup lang="ts">
import {computed,nextTick,onMounted,ref,watch} from 'vue'
import {useStudio} from './studioContext'
import PeopleBrowser from './PeopleBrowser.vue'
import AppIcon from './AppIcon.vue'
import RelationshipGraph from './RelationshipGraph.vue'
import ReviewUnit from './ReviewUnit.vue'
import {editLibraryField,editLibraryRow,libraryFields} from './structuredRuntime'
import {clone} from './editRuntime'
const s=useStudio(),emit=defineEmits<{running:[value:boolean]}>()
const preview=ref<any>(null),error=ref(''),showAll=ref(false),previewPolicy=ref<any>(null)
const target=ref<{kind:string;section:string;itemIds:string[]}|null>(null),chosen=ref<Record<string,string[]>>({})
const drawer=ref<HTMLDialogElement>(),references=ref<any[]>([]),referenceIndex=ref(0)
const sections=[{id:'artwork',label:'作品档案'},{id:'people',label:'画中人物'},{id:'relations',label:'人物关系'},{id:'events',label:'历史背景与事件'},{id:'research',label:'研究判断'},{id:'sources',label:'来源概况'}]
const columns=[sections.filter(section=>section.id!=='people'),sections.filter(section=>section.id==='people')]
const material=computed(()=>s.rec('material','main')),data=computed<any>(()=>material.value?.draft.structured||preview.value)
const conflicts=computed(()=>data.value?.conflicts.filter((c:any)=>c.kind==='contradiction'&&c.status!=='retired'&&!['current','candidate'].includes(c.resolution))||[])
const people=computed(()=>[...(data.value?.people||[])].sort((a:any,b:any)=>Number(!!b.characterId||b.scope==='depicted')-Number(!!a.characterId||a.scope==='depicted')))
const shownPeople=computed(()=>showAll.value?people.value:people.value.slice(0,4))
const targetLabel=computed(()=>{if(!target.value)return '';const label=sections.find(v=>v.id===target.value!.section)?.label||'资料争议';return label+(target.value.itemIds.length?` · 已选 ${target.value.itemIds.length} 项`:' · 整个模块')})
const evidence=computed(()=>references.value[referenceIndex.value]),source=computed(()=>data.value?.sources.find((v:any)=>v.id===evidence.value?.sourceId&&v.version===evidence.value?.sourceVersion))
const policy=computed(()=>!material.value?.draft.structured&&previewPolicy.value?previewPolicy.value:s.p.value.peoplePolicy||{mainIds:people.value.filter((r:any)=>r.characterId).map((r:any)=>r.id),candidateIds:people.value.filter((r:any)=>!r.characterId&&r.scope==='depicted').map((r:any)=>r.id),otherIds:people.value.filter((r:any)=>!r.characterId&&r.scope!=='depicted').map((r:any)=>r.id),duplicateGroups:[]})
const sourceCount=computed(()=>new Set((data.value?.sources||[]).map((r:any)=>r.documentId||r.id)).size)
const covered=computed(()=>new Set((s.p.value.documentAnalysis?.coverage||[]).filter((v:any)=>!v.failed).flatMap((v:any)=>v.pages.map((p:any)=>p.documentId))))
const pendingSources=computed(()=>s.p.value.documents.filter((d:any)=>!covered.value.has(d.id)||(s.p.value.documentAnalysis?.failedPages||[]).some((p:any)=>p.documentId===d.id)||(s.p.value.documentAnalysis?.analyzedSources&&s.p.value.sources.filter((r:any)=>r.documentId===d.id).some((r:any)=>!s.p.value.documentAnalysis.analyzedSources.some((a:any)=>a.id===r.id&&a.version===r.version)))))
function brief(text:string,limit=180){return (text||'').length>limit?text.slice(0,limit)+'…':text||'现有资料尚未提供。'}
function summary(section:string){if(section==='people')return '以画中角色为主，其他人物提及按需查看。';if(data.value?.summaryBlocks?.[section]?.text)return data.value.summaryBlocks[section].text;if(section==='artwork')return brief(data.value.artwork.storyOneLiner.value||data.value.artwork.description.value||data.value.artwork.name.value);if(section==='people')return `${people.value.length} 位资料人物，按画中候选优先显示。`;if(section==='sources')return `${sourceCount.value} 个来源，${data.value.evidence.length} 处逐字依据。`;return brief((data.value[section]||[]).slice(0,2).map((r:any)=>r.text||relation(r)).join('；'))}
function profile(person:any){return brief(person.summary||data.value.statements.filter((r:any)=>r.personId===person.id).map((r:any)=>r.text).join('；'))}
function relation(row:any){const name=(id:string)=>data.value.people.find((p:any)=>p.id===id)?.name||'未知';return `${name(row.fromId)} → ${row.label} → ${name(row.toId)}`}
function sectionConflicts(section:string,id?:string){return conflicts.value.filter((c:any)=>c.field.startsWith(section+'.')&&(!id||c.field.split('.')[1]===id))}
function select(section:string,ids:string[]=[]){target.value={kind:'library',section,itemIds:ids};s.openSmartEdit(target.value,targetLabel.value,prepareFeedback)}
function toggle(section:string,id:string,checked:boolean){const ids=new Set(chosen.value[section]||[]);checked?ids.add(id):ids.delete(id);chosen.value[section]=[...ids];target.value=ids.size?{kind:'library',section,itemIds:[...ids]}:null;if(target.value)s.openSmartEdit(target.value,targetLabel.value,prepareFeedback,false)}
function edit(){if(!material.value.draft.structured)material.value.draft.structured=clone(preview.value);return material.value.draft.structured}
function field(key:string,value:string){editLibraryField(edit(),key,value);s.scheduleAutosave()}
function row(section:string,item:any,key:string,value:string){editLibraryRow(edit(),section,item.id,key,value);s.scheduleAutosave()}
async function load(){preview.value=null;error.value='';if(material.value?.draft.structured)return;const pid=s.p.value.id;try{const r=await s.api(`/projects/${pid}/structured`);if(pid===s.p.value.id){preview.value=r.draft;previewPolicy.value=r.peoplePolicy}}catch(e:any){error.value=e.message}}
async function locate(ids:string[]){references.value=(ids||[]).map(id=>data.value.evidence.find((e:any)=>e.id===id)).filter(Boolean);referenceIndex.value=0;if(!references.value.length)return;await nextTick();drawer.value?.showModal()}
async function resolve(c:any,resolution:string){await s.saveAll();if(!material.value.draft.structured){edit();await s.saveAll()}await s.runSmartAction({kind:'library',section:'conflicts',itemIds:[c.id]},{resolution},prepareFeedback)}
async function prepareFeedback(){if(!material.value.draft.structured){edit();await s.saveAll()}}
function updated(){preview.value=null;chosen.value={};if(target.value?.itemIds.length){const rows=target.value.section==='artwork'?Object.keys(data.value?.artwork||{}):(data.value?.[target.value.section]||[]).map((r:any)=>r.id);target.value.itemIds=target.value.itemIds.filter(id=>rows.includes(id));if(!target.value.itemIds.length)target.value=null}}
onMounted(load);watch(()=>s.p.value.id,()=>{target.value=null;chosen.value={};drawer.value?.close();void load()})
</script>
<template><section class="library-summary" aria-label="画作资料摘要面板">
 <div class="summary-heading"><div><span class="summary-eyebrow">整合后的画作资料</span><h2>{{data?.artwork.name.value||s.p.value.artworkName}}</h2><p>{{data?brief(data.artwork.storyOneLiner.value||data.artwork.description.value,180):'添加多个来源后，点击整理资料，生成一份清晰的画作摘要。'}}</p></div><ReviewUnit v-if="material?.draft.structured" unit-id="library:main" label="核对整份资料"/></div>
 <p v-if="error" role="alert">{{error}}</p>
 <template v-if="data"><div class="summary-metrics"><span>{{sourceCount}} 个资料来源</span><span>{{covered.size}} 份文献已处理</span><span v-if="pendingSources.length">{{pendingSources.length}} 份文献待处理</span><span :class="{disputed:conflicts.length}">{{conflicts.length}} 处真实争议</span></div>
 <p v-if="pendingSources.length" class="coverage-note">新增或尚未覆盖的文献：{{pendingSources.map((d:any)=>d.title).join('、')}}。点击“整理资料”后纳入。</p>
 <div class="summary-grid"><div v-for="(column,index) in columns" :key="index" class="summary-column"><section v-for="section in column" :key="section.id" class="summary-module" :class="{selected:target?.section===section.id}" :aria-label="section.label+'摘要'">
  <header><h3>{{section.label}}</h3><button @click="select(section.id)"><AppIcon name="ai" :size="13"/>智能修改</button></header><p class="module-summary">{{summary(section.id)}}</p>
  <PeopleBrowser v-if="section.id==='people'" :data="data" :policy="policy" :prepare="prepareFeedback" @locate="locate" @smart="select('people',$event)"/>
  <details v-else-if="section.id==='artwork'"><summary>展开作品字段</summary><div v-for="(label,key) in libraryFields" :key="key" class="detail-item"><b>{{label}}</b><p>{{data.artwork[key]?.value||'资料未提供'}}</p><div class="item-actions"><button @click="select('artwork',[key])">修改此项</button><button :disabled="!data.artwork[key]?.referenceIds?.length" @click="locate(data.artwork[key].referenceIds)">对应原文</button></div><details><summary>直接编辑</summary><textarea :value="data.artwork[key]?.value" @input="field(key,($event.target as HTMLTextAreaElement).value)"/></details></div></details>
  <details v-else-if="section.id==='sources'"><summary>展开来源与处理状态</summary><div v-for="sourceRow in data.sources" :key="sourceRow.id+':'+sourceRow.version" class="detail-item"><b>{{sourceRow.title}}</b><small>版本 {{sourceRow.version}} {{sourceRow.page?'· 第 '+sourceRow.page+' 页':''}}</small><p>{{sourceRow.citation||'未提供书目信息'}}</p><button :disabled="!data.evidence.some((e:any)=>e.sourceId===sourceRow.id&&e.sourceVersion===sourceRow.version)" @click="locate(data.evidence.filter((e:any)=>e.sourceId===sourceRow.id&&e.sourceVersion===sourceRow.version).map((e:any)=>e.id))">查看引文与原文</button></div></details>
  <details v-else><summary>展开{{section.label}}详情（{{data[section.id].length}}）</summary><RelationshipGraph v-if="section.id==='relations'" :people="data.people" :relations="data.relations" :evidence="data.evidence" :published-relations="material?.published?.structured?.relations||[]"/><article v-for="item in data[section.id]" :key="item.id" class="detail-item"><label><input type="checkbox" :checked="chosen[section.id]?.includes(item.id)" @change="toggle(section.id,item.id,($event.target as HTMLInputElement).checked)"><b>{{item.title||item.topic||(section.id==='relations'?relation(item):section.label)}}</b></label><p>{{item.text}}</p><small v-if="item.category==='inference'||item.category==='uncertain'">{{item.category==='inference'?'研究解释／推断':'尚待核对'}}</small><div class="item-actions"><button @click="select(section.id,[item.id])">修改此项</button><button :disabled="!item.referenceIds?.length" @click="locate(item.referenceIds)">对应原文</button></div><details><summary>直接编辑</summary><textarea :value="section.id==='relations'?item.label:item.text" @input="row(section.id,item,section.id==='relations'?'label':'text',($event.target as HTMLTextAreaElement).value)"/></details></article></details>
  <details v-for="c in sectionConflicts(section.id)" :key="c.id" class="conflict-card"><summary>争议 · {{c.reason}} <small v-if="c.resolution==='keep_both'">已选择保留分歧</small></summary><p>{{c.context}}</p><div v-for="(alternative,index) in c.alternatives" :key="index" class="conflict-alternative"><p><b>{{index===0?'A':'B'}}：</b>{{alternative.value}}</p><button @click="locate(alternative.referenceIds)">查看此说法原文</button></div><div class="item-actions"><button :disabled="s.generating.value" @click="resolve(c,'current')">采用 A</button><button :disabled="s.generating.value" @click="resolve(c,'candidate')">采用 B</button><button :disabled="s.generating.value" @click="resolve(c,'keep_both')">保留分歧</button><button @click="select('conflicts',[c.id])"><AppIcon name="ai" :size="13"/>智能修改</button></div></details>
 </section></div></div>
 <details v-if="data.missing.length" class="missing-details"><summary>查看资料缺失与核对提示（不计入争议）</summary><p v-for="(item,i) in data.missing" :key="i"><b>{{item.label}}</b>：{{item.reason}}</p></details>

 </template>
 <dialog ref="drawer" class="evidence-drawer" aria-label="对应原文" @click="($event.target===drawer)&&drawer?.close()"><template v-if="evidence&&source"><header><h3>{{source.title}}</h3><button aria-label="关闭原文" @click="drawer?.close()">关闭 ×</button></header><p>来源版本 {{evidence.sourceVersion}} {{evidence.page?'· 第 '+evidence.page+' 页':''}} · {{source.citation||'出处未注明'}}</p><label v-if="references.length>1">切换引用<select v-model="referenceIndex"><option v-for="(r,i) in references" :key="r.id" :value="i">{{i+1}} · {{r.quote.slice(0,45)}}</option></select></label><blockquote>{{evidence.quote}}</blockquote><small>{{evidence.level==='indirect'?'研究资料转引，未独立核对原书':evidence.verification==='edition_verified'?'已人工核对原书版本':'保留原文，尚未独立核对版本'}}</small><details open><summary>对应版本完整原文</summary><pre>{{source.text.slice(0,evidence.start)}}<mark>{{evidence.quote}}</mark>{{source.text.slice(evidence.end)}}</pre></details><img v-if="source.documentId&&s.p.value.documents.find((d:any)=>d.id===source.documentId)?.format!=='text'" :src="`/api/projects/${s.p.value.id}/documents/${source.documentId}/pages/${source.page||evidence.page||1}`" alt="对应文献原页"/></template></dialog>
</section></template>
<style scoped>
.library-summary{margin-bottom:24px}.summary-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.summary-heading h2{font-size:25px;margin:9px 0}.summary-heading p{font-size:13px;line-height:1.9;color:#7d8c7d;max-width:780px}.summary-eyebrow{font-size:10px;letter-spacing:.08em;color:#819579}.summary-metrics{display:flex;gap:9px;flex-wrap:wrap;margin:15px 0 20px}.summary-metrics span{font-size:11px;border-radius:20px;padding:6px 11px;background:#eef3e8;color:#6d8264}.summary-metrics .disputed{background:#fcf0df;color:#9a733b}.coverage-note{font-size:12px;color:#8b805c}.summary-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start}.summary-column{display:flex;flex-direction:column;gap:16px;min-width:0}.summary-module{min-width:0;border:1px solid #e0e6d8;border-radius:12px;padding:20px;background:#fffef9}.summary-module.selected{border-color:#83a389;box-shadow:0 0 0 2px #93b49c1a}.summary-module header{display:flex;align-items:center;justify-content:space-between;gap:12px}.summary-module h3{margin:0;font-size:14px;color:#42573c}.summary-module button{font-size:11px;padding:5px 9px}.summary-module header button{border:0;background:#edf3e8;color:#5e7c50;white-space:nowrap}.module-summary{font-size:12px;line-height:1.95;color:#74816d;margin:14px 0}.summary-module summary{font-size:11px;color:#7d8b73;cursor:pointer}.summary-person{border-top:1px solid #edf0e5;padding:13px 0}.person-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.person-heading label,.detail-item>label{display:flex;align-items:center;gap:7px;font-size:12px;margin:0}.summary-person input,.detail-item input{width:auto}.person-heading small,.summary-person>small{color:#929a86;font-size:10px}.summary-person p,.detail-item p{font-size:12px;line-height:1.9;color:#64705a;margin:8px 0}.item-actions{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}.summary-person details{margin-top:10px}.detail-item{padding:13px 0;border-top:1px solid #e8edde;font-size:12px;overflow-wrap:anywhere}.detail-item>small{display:block;font-size:10px;color:#8b947d;margin-top:6px}.detail-item textarea{font-size:12px;margin-top:8px}.show-people{width:100%;margin-top:7px}.conflict-card{margin-top:12px;border-left:3px solid #cda86c;background:#fdf5e9;padding:12px;border-radius:5px}.conflict-card summary{color:#94713b}.conflict-card p{font-size:12px;line-height:1.8}.conflict-alternative{border-top:1px solid #eddfc8;padding:7px 0}.inline-dispute{color:#a07a40!important}.missing-details{font-size:11px;color:#8c937d;margin-top:18px}.missing-details p{font-size:12px}.evidence-drawer{position:fixed;inset:0 0 0 auto;margin:0;width:min(720px,94vw);height:100dvh;max-height:100dvh;border:0;border-left:1px solid #d9e3d4;padding:28px;background:#fffef9;overflow:auto;color:#4b6042;box-sizing:border-box}.evidence-drawer::backdrop{background:#19332145}.evidence-drawer header{display:flex;justify-content:space-between;gap:20px;align-items:center}.evidence-drawer h3{font-size:17px}.evidence-drawer p,.evidence-drawer small{font-size:12px;line-height:1.8}.evidence-drawer blockquote{font-size:13px;line-height:2;padding:15px;border-left:3px solid #a8bd91;background:#f3f7ed;margin:18px 0}.evidence-drawer pre{white-space:pre-wrap;font-size:12px;line-height:2;overflow-wrap:anywhere}.evidence-drawer mark{background:#f4e7ae}.evidence-drawer img{max-width:100%;margin-top:18px}.evidence-drawer summary{font-size:12px;margin-top:20px}</style>
